import json, subprocess, sys

def run(req):
    p = subprocess.run(['/app/submission/run.sh'], input=json.dumps(req).encode(),
                       capture_output=True, cwd='/app/submission')
    assert p.returncode == 0, (p.returncode, p.stderr.decode()[:500])
    return json.loads(p.stdout.decode())

fails = []
def check(name, got, exp):
    if got != exp:
        fails.append(name); print('FAIL', name, '\n  got', got, '\n  exp', exp)
    else: print('ok  ', name)

def truth(atom, K, schema, true_rows, false_rows, groups):
    """groups: list of row-lists, each its own query trace.
    Returns per-context truth of the single atom (via must/may of the one class)."""
    req = {"version":1,"window":K,"schema":schema,"atoms":[atom],
           "policy":{"max_width":1,"min_support":1,"min_witness":1},
           "train":[{"id":"t","source":"s","rows":[{"t":i,"values":r} for i,r in enumerate(true_rows)]}],
           "probes":[{"id":"p","source":"s","rows":[{"t":i,"values":r} for i,r in enumerate(false_rows)]}],
           "queries":[{"id":"q%d"%g,"source":"s","rows":[{"t":i,"values":r} for i,r in enumerate(rows)]}
                      for g,rows in enumerate(groups)]}
    r = run(req)
    if len(r.get('classes',[])) != 1:
        return 'NOCLASS:%s' % json.dumps(r)
    nctx = sum(max(0, len(rows)-K+1) for rows in groups)
    assert len(r['queries']) == nctx, (len(r['queries']), nctx)
    return [q['must'] == 0 for q in r['queries']]

CNT2 = [{"name":"x","type":"COUNT","min":-1000,"max":1000},{"name":"y","type":"COUNT","min":-1000,"max":1000}]
CNT1 = [{"name":"x","type":"COUNT","min":-1000,"max":1000}]
BIG = [{"name":"x","type":"TIME","min":-2147483648,"max":2147483647}]
meanx = lambda a,z: {"aggregate":"mean","field":"x","from":a,"to":z}
meany = lambda a,z: {"aggregate":"mean","field":"y","from":a,"to":z}
c = lambda v,t="COUNT": {"const":v,"type":t}

# 1/3 + 2/3 == 1 exactly (naive float -> 0.9999999999999999)
atom = {"cmp":"eq","left":{"add":[meanx(0,2), meany(0,2)]},"right":c(1)}
T = [[1,1],[0,1],[0,0]]
F = [[0,0],[0,0],[0,0]]
check('1/3+2/3 == 1 exact', truth(atom,3,CNT2,T,F,[T,F,T]), [True, False, True])

# 1/3 + 1 (mean y over 0..1 of [1,1]) = 4/3 -> *6 = 8
atom3 = {"cmp":"eq","left":{"scale":6,"term":{"add":[meanx(0,2), meany(0,1)]}},"right":c(8)}
check('6*(1/3+1) == 8', truth(atom3,3,CNT2,T,F,[T,F]), [True, False])
# 1/3 + 1/2 = 5/6 -> *6 = 5
T2 = [[1,1],[0,0],[0,0]]
atom2 = {"cmp":"eq","left":{"scale":6,"term":{"add":[meanx(0,2), meany(0,1)]}},"right":c(5)}
check('6*(1/3+1/2) == 5', truth(atom2,3,CNT2,T2,F,[T2,F,T2]), [True, False, True])
check('6*(1/3+1/2) != 8', truth(atom3,3,CNT2,T,F,[T2,F]), [False, False])

# mean 2/3 > 0 ; mean 2/3 >= 1 false
T3 = [[1],[1],[0]]
F3 = [[0],[0],[0]]
atom4 = {"cmp":"gt","left":meanx(0,2),"right":c(0)}
check('mean 2/3 > 0', truth(atom4,3,CNT1,T3,F3,[T3,F3]), [True, False])
atom4b = {"cmp":"ge","left":meanx(0,2),"right":c(1)}
check('mean 2/3 >= 1 false', truth(atom4b,3,CNT1,T3,F3,[T3,F3]), [False, False])

# scale -3 * 2/3 == -2 exactly
atom5 = {"cmp":"eq","left":{"scale":-3,"term":meanx(0,2)},"right":c(-2)}
check('scale -3 * 2/3 == -2', truth(atom5,3,CNT1,T3,F3,[T3,F3]), [True, False])

# 2*mean(1..8) == 9 ; mean(1..8) < 5
rows18 = [[i] for i in range(1,9)]
F18 = [[0]]*8
atom6 = {"cmp":"eq","left":{"scale":2,"term":meanx(0,7)},"right":c(9)}
check('2*mean(1..8) == 9', truth(atom6,8,CNT1,rows18,F18,[rows18,F18]), [True, False])
atom7 = {"cmp":"lt","left":meanx(0,7),"right":c(5)}
check('mean(1..8) < 5', truth(atom7,8,CNT1,rows18,F18,[rows18,F18]), [True, False])

# unbounded arithmetic: mean([2^31-1, 2^31-2]) = 4294967293/2, *2 = 4294967293 > i32
BH = [[2147483647],[2147483646]]
BF = [[0],[0]]
atom8 = {"cmp":"gt","left":{"scale":2,"term":meanx(0,1)},"right":c(2147483647,"TIME")}
check('unbounded gt', truth(atom8,2,BIG,BH,BF,[BH,BF]), [True, False])
atom9 = {"cmp":"eq","left":meanx(0,1),"right":c(2147483646,"TIME")}
check('mean not floored (eq 2147483646)', truth(atom9,2,BIG,BH,BF,[BH,BF]), [False, False])
atom10 = {"cmp":"gt","left":meanx(0,1),"right":c(2147483646,"TIME")}
check('mean > 2147483646', truth(atom10,2,BIG,BH,BF,[BH,BF]), [True, False])
atom11 = {"cmp":"lt","left":meanx(0,1),"right":c(2147483647,"TIME")}
check('mean < 2147483647', truth(atom11,2,BIG,BH,BF,[BH,BF]), [True, False])

# min/max/sum
T12 = [[5],[-3],[2]]
F12 = [[0],[0],[0]]
atom12 = {"cmp":"eq","left":{"aggregate":"min","field":"x","from":0,"to":2},"right":c(-3)}
check('min aggregate', truth(atom12,3,CNT1,T12,F12,[T12,F12]), [True, False])
atom13 = {"cmp":"eq","left":{"aggregate":"max","field":"x","from":0,"to":2},"right":c(5)}
check('max aggregate', truth(atom13,3,CNT1,T12,F12,[T12,F12]), [True, False])
atom14 = {"cmp":"eq","left":{"aggregate":"sum","field":"x","from":0,"to":2},"right":c(4)}
check('sum aggregate', truth(atom14,3,CNT1,T12,F12,[T12,F12]), [True, False])

# quantifier with $ and mean mixed: all j in 0..2: x[j] + mean(x,0..2) > 0
atom15 = {"quantifier":"all","from":0,"to":2,
          "predicate":{"cmp":"gt","left":{"add":[{"field":"x","at":"$"},meanx(0,2)]},"right":c(0)}}
T15 = [[1],[0],[2]]   # mean = 1 ; 1+1, 0+1, 2+1 all > 0
F15 = [[-5],[0],[0]]  # mean = -5/3 ; -5-5/3 < 0
check('quantifier all $ + mean', truth(atom15,3,CNT1,T15,F15,[T15,F15]), [True, False])
atom16 = {"quantifier":"any","from":0,"to":2,
          "predicate":{"cmp":"eq","left":{"field":"x","at":"$"},"right":c(2)}}
check('quantifier any eq', truth(atom16,3,CNT1,T12,F12,[T12,F12]), [True, False])
atom17 = {"quantifier":"all","from":1,"to":2,
          "predicate":{"cmp":"ge","left":{"field":"x","at":"$"},"right":c(-3)}}
check('quantifier subrange all', truth(atom17,3,CNT1,T12,F12,[T12,F12]), [True, False])
# body without $ inside a quantifier: evaluated once, same for every binding
atom18 = {"quantifier":"any","from":0,"to":2,
          "predicate":{"cmp":"eq","left":meanx(0,2),"right":c(1)}}
check('quantifier body without $', truth(atom18,3,CNT1,T3,F3,[T3,F3]), [True, False])
print('failures:', len(fails))
PYEOF
